/**
 * The schemas of `zod.ts`, each scenario's root compiled by `z.compile`, Zod's
 * ahead-of-time mode: a clone of the schema whose `safeParse` runs a parser
 * generated by `new Function` when it is compiled, which builds the output of
 * a valid input and hands an invalid one to the regular parser. A root
 * `z.compile` can't compile, as the recursive one of `type_json`, it hands back
 * unchanged, and the timings print no figure of that scenario for
 * `zod_compiled`, see `schemas/zod_compiled.ts`: timed here, the root handed
 * back is Zod's runtime parser in a process of compiled schemas, and reads as
 * neither library's.
 *
 * The schemas are `zod.ts`'s written again, as every module here holds its
 * own, which `src/test/benchmarks.test.ts` holds to the same verdicts and
 * outputs. Each root is compiled by `z.compile` and not by importing
 * `zod/compile`, which would compile plain `zod`'s schemas too in a process
 * that loads both.
 *
 * @module
 */

import * as z from 'zod';

import type { ScenarioModule, ScenarioRunner } from '../scenarios.ts';

const to_runner = (schema: z.ZodType): ScenarioRunner => {
	const compiled = z.compile(schema);
	return (value) => compiled.safeParse(value).success;
};

export const scenario_string: ScenarioModule['scenario_string'] = () => to_runner(z.string());

export const scenario_object_flat: ScenarioModule['scenario_object_flat'] = () =>
	to_runner(
		z.object({
			id: z.number(),
			name: z.string(),
			email: z.string(),
			active: z.boolean(),
			role: z.optional(z.string())
		})
	);

export const scenario_extra_keys: ScenarioModule['scenario_extra_keys'] = scenario_object_flat;

export const scenario_strict_nested: ScenarioModule['scenario_strict_nested'] = () =>
	to_runner(
		z.strictObject({
			id: z.number(),
			name: z.string(),
			tags: z.array(z.string()),
			address: z.strictObject({ street: z.string(), city: z.string(), zip: z.string() })
		})
	);

export const scenario_pipe: ScenarioModule['scenario_pipe'] = () =>
	to_runner(
		z.object({
			name: z.string().min(1).max(50),
			age: z.int().min(0).max(150),
			slug: z.string().regex(/^[a-z0-9-]+$/)
		})
	);

export const scenario_union: ScenarioModule['scenario_union'] = () =>
	to_runner(z.array(z.union([z.string(), z.number(), z.boolean()])));

export const scenario_list: ScenarioModule['scenario_list'] = () =>
	to_runner(
		z.array(
			z.strictObject({
				id: z.number(),
				name: z.string(),
				email: z.string(),
				active: z.boolean(),
				role: z.optional(z.string()),
				tags: z.array(z.string())
			})
		)
	);

export const scenario_type_json: ScenarioModule['scenario_type_json'] = () => {
	const TypeJson: z.ZodType = z.discriminatedUnion('kind', [
		z.strictObject({ kind: z.literal('intrinsic'), text: z.string() }),
		z.strictObject({
			kind: z.literal('literal'),
			// zod's `number` is already finite
			value: z.union([z.string(), z.number(), z.boolean()]),
			text: z.string()
		}),
		z.strictObject({
			kind: z.literal('reference'),
			name: z.string(),
			module: z.optional(z.string()),
			typeArgs: z.optional(z.array(z.lazy(() => TypeJson)))
		}),
		z.strictObject({
			kind: z.literal('array'),
			element: z.lazy(() => TypeJson),
			readonly: z.optional(z.boolean())
		}),
		z.strictObject({
			kind: z.literal('tuple'),
			elements: z.optional(z.array(z.lazy(() => TupleElementJson))),
			readonly: z.optional(z.boolean())
		}),
		z.strictObject({
			kind: z.literal('union'),
			alias: z.optional(z.string()),
			members: z.array(z.lazy(() => TypeJson))
		}),
		z.strictObject({
			kind: z.literal('intersection'),
			alias: z.optional(z.string()),
			members: z.array(z.lazy(() => TypeJson))
		}),
		z.strictObject({ kind: z.literal('function'), text: z.string() }),
		z.strictObject({ kind: z.literal('object'), text: z.string() }),
		z.strictObject({ kind: z.literal('other'), text: z.string() })
	]);
	const TupleElementJson: z.ZodType = z.strictObject({
		name: z.optional(z.string()),
		type: TypeJson,
		optional: z.optional(z.boolean()),
		rest: z.optional(z.boolean())
	});
	return to_runner(TypeJson);
};

// every schema parses its own key, whatever the others gave, each a root compiled
const to_app_runner = (app: Record<string, z.ZodType>): ScenarioRunner => {
	const compiled = Object.fromEntries(
		Object.entries(app).map(([key, schema]) => [key, z.compile(schema)])
	);
	return (value: any) => {
		let ok = true;
		for (const key in compiled) ok = compiled[key]!.safeParse(value[key]).success && ok;
		return ok;
	};
};

export const scenario_app: ScenarioModule['scenario_app'] = () => {
	const id = z.int().min(1);
	const count = z.int().min(0);
	const money = z.number().min(0);
	return to_app_runner({
		user: z.strictObject({
			id,
			name: z.string().min(1).max(100),
			email: z.string().regex(/^[^@\s]+@[^@\s]+$/),
			role: z.enum(['member', 'admin', 'owner']),
			created_at: z.string(),
			avatar_url: z.optional(z.string())
		}),
		post: z.strictObject({
			id,
			author_id: id,
			title: z.string().min(1).max(200),
			body: z.string(),
			tags: z.array(z.string()),
			published: z.boolean(),
			published_at: z.nullable(z.string())
		}),
		comment: z.strictObject({
			id,
			post_id: id,
			author_id: id,
			body: z.string().min(1),
			reply_to: z.optional(id)
		}),
		page: z.strictObject({
			page: id,
			per_page: z.int().min(1).max(100),
			total: count,
			next_cursor: z.nullable(z.string())
		}),
		error: z.strictObject({
			error: z.strictObject({
				code: z.string(),
				message: z.string(),
				details: z.optional(
					z.array(z.strictObject({ path: z.array(z.string()), message: z.string() }))
				)
			})
		}),
		settings: z.strictObject({
			theme: z.enum(['light', 'dark', 'system']),
			language: z.string(),
			notifications: z.strictObject({
				email: z.boolean(),
				push: z.boolean(),
				digest: z.enum(['daily', 'weekly', 'never'])
			}),
			timezone: z.optional(z.string())
		}),
		address: z.strictObject({
			street: z.string(),
			city: z.string(),
			region: z.optional(z.string()),
			postal_code: z.string(),
			country: z.string().min(2).max(2)
		}),
		product: z.strictObject({
			id: z.string(),
			name: z.string(),
			price: money,
			currency: z.enum(['usd', 'eur', 'gbp']),
			stock: count,
			categories: z.array(z.string())
		}),
		order: z.strictObject({
			id: z.string(),
			user_id: id,
			items: z.array(z.strictObject({ product_id: z.string(), quantity: id, unit_price: money })),
			status: z.enum(['pending', 'paid', 'shipped', 'cancelled']),
			total: money
		}),
		event: z.discriminatedUnion('type', [
			z.strictObject({ type: z.literal('login'), at: z.number(), ip: z.string() }),
			z.strictObject({ type: z.literal('logout'), at: z.number() }),
			z.strictObject({ type: z.literal('purchase'), at: z.number(), order_id: z.string() })
		])
	});
};
